B=[
('بَغْدَادُ','Bağdat',[
('كَانَتْ بَغْدَادُ فِي عَهْدِ هَارُونَ الرَّشِيدِ أَعْظَمَ مُدُنِ الدُّنْيَا.','Hârûnürreşîd devrinde Bağdat dünyanın en büyük şehriydi.'),
('تَجْرِي فِيهَا السُّفُنُ عَلَى دِجْلَةَ، وَتَمْتَلِئُ أَسْوَاقُهَا بِالتُّجَّارِ مِنَ الصِّينِ وَالْهِنْدِ وَالرُّومِ.','Dicle’de gemiler yüzüyor, çarşıları Çin’den, Hindistan’dan ve Rum’dan gelen tüccarlarla doluyordu.'),
('وَكَانَ لِلْخَلِيفَةِ وَزِيرٌ عَظِيمٌ اسْمُهُ جَعْفَرٌ الْبَرْمَكِيُّ، وَهُوَ صَدِيقُهُ الْحَمِيمُ.','Halifenin Ca‘fer el-Bermekî adında büyük bir veziri vardı; o, yakın dostuydu.'),
('وَكَانَ الْبَرَامِكَةُ أُسْرَةً كَرِيمَةً، يُعْطُونَ الْعُلَمَاءَ وَالشُّعَرَاءَ وَالْفُقَرَاءَ.','Bermekîler âlimlere, şairlere ve fakirlere bağışta bulunan cömert bir aileydi.'),
('وَكَانَ لِلرَّشِيدِ أُخْتٌ ذَكِيَّةٌ جَمِيلَةٌ اسْمُهَا الْعَبَّاسَةُ.','Reşîd’in Abbâse adında zeki ve güzel bir kız kardeşi vardı.'),
('وَكَانَ الرَّشِيدُ يُحِبُّ أَنْ يَجْلِسَ مَعَ جَعْفَرٍ وَالْعَبَّاسَةِ يَتَحَدَّثُونَ فِي الشِّعْرِ وَالْأَدَبِ.','Reşîd, Ca‘fer ve Abbâse ile oturup şiir ve edebiyat konuşmayı severdi.')]),
('الشَّرْطُ','Şart',[
('فَقَالَ الرَّشِيدُ: «لَا أَسْتَطِيعُ الصَّبْرَ عَنْكُمَا، وَلَا يَحِلُّ أَنْ تَجْلِسَا مَعًا وَأَنْتُمَا أَجْنَبِيَّانِ.»','Reşîd dedi ki: “Sizden ayrı duramıyorum; ama siz yabancıyken birlikte oturmanız helal değil.”'),
('«فَأُزَوِّجُكَ يَا جَعْفَرُ أُخْتِي، عَلَى أَنْ يَكُونَ الزَّوَاجُ لِلْمَجْلِسِ فَقَطْ.»','“Ey Ca‘fer, kız kardeşimi seninle evlendiriyorum; ama evlilik yalnızca meclis için olacak.”'),
('هَكَذَا تَرْوِي الْحِكَايَةُ الَّتِي بَنَى عَلَيْهَا زَيْدَانُ رِوَايَتَهُ.','Zeydân’ın romanını üzerine kurduğu rivayet böyle anlatır.'),
('فَوَافَقَ جَعْفَرٌ، وَلَكِنَّ الْقُلُوبَ لَا تُطِيعُ الشُّرُوطَ.','Ca‘fer kabul etti; ama kalpler şartlara uymaz.'),
('فَأَحَبَّ كُلٌّ مِنْهُمَا الْآخَرَ حُبًّا صَادِقًا، وَتَزَوَّجَا زَوَاجًا حَقِيقِيًّا فِي السِّرِّ.','Her biri diğerini gerçekten sevdi ve gizlice gerçek bir evlilik yaptılar.'),
('وَوُلِدَ لَهُمَا طِفْلٌ، فَأَرْسَلَتْهُ الْعَبَّاسَةُ سِرًّا إِلَى مَكَّةَ مَعَ خَادِمَةٍ أَمِينَةٍ.','Bir çocukları doğdu; Abbâse onu güvenilir bir hizmetçiyle gizlice Mekke’ye gönderdi.')]),
('الْحُسَّادُ','Kıskançlar',[
('وَكَانَ فِي الْقَصْرِ رِجَالٌ يَحْسُدُونَ الْبَرَامِكَةَ عَلَى قُرْبِهِمْ مِنَ الْخَلِيفَةِ.','Sarayda Bermekîleri halifeye yakınlıkları yüzünden kıskanan adamlar vardı.'),
('وَأَشْهَرُهُمُ الْفَضْلُ بْنُ الرَّبِيعِ، فَكَانَ يَبْحَثُ عَنْ عَيْبٍ فِيهِمْ.','En meşhurları Fazl b. Rebî‘ idi; onlarda bir kusur arıyordu.'),
('وَكَانَ الْبَرَامِكَةُ قَدْ صَارَ لَهُمْ مِنَ الْمَالِ وَالْقُصُورِ مَا لَمْ يَكُنْ لِلْخَلِيفَةِ نَفْسِهِ.','Bermekîlerin, halifenin kendisinde bile olmayan kadar malı ve sarayı olmuştu.'),
('فَقَالَ الْحُسَّادُ لِلرَّشِيدِ: «انْظُرْ إِلَى قُصُورِهِمْ؛ إِنَّهُمْ يُرِيدُونَ الْمُلْكَ لِأَنْفُسِهِمْ.»','Kıskançlar Reşîd’e dediler ki: “Saraylarına bak; hükümranlığı kendileri için istiyorlar.”'),
('وَعَلِمَ أَحَدُهُمْ بِأَمْرِ الطِّفْلِ فِي مَكَّةَ، فَأَخْبَرَ الْخَلِيفَةَ.','İçlerinden biri Mekke’deki çocuğu öğrendi ve halifeye haber verdi.'),
('فَتَغَيَّرَ وَجْهُ الرَّشِيدِ، وَسَكَتَ طَوِيلًا.','Reşîd’in yüzü değişti ve uzun süre sustu.')]),
('نَكْبَةُ الْبَرَامِكَةِ','Bermekîlerin felaketi',[
('وَفِي سَنَةِ مِائَةٍ وَسَبْعٍ وَثَمَانِينَ رَجَعَ الرَّشِيدُ مِنَ الْحَجِّ إِلَى الْعِرَاقِ.','187 yılında Reşîd hacdan Irak’a döndü.'),
('وَفِي لَيْلَةٍ مُظْلِمَةٍ أَمَرَ بِقَتْلِ جَعْفَرٍ، وَهُوَ صَدِيقُهُ مُنْذُ الطُّفُولَةِ.','Karanlık bir gecede çocukluğundan beri dostu olan Ca‘fer’in öldürülmesini emretti.'),
('وَحُبِسَ أَبُوهُ يَحْيَى وَإِخْوَتُهُ، وَأُخِذَتْ أَمْوَالُهُمْ.','Babası Yahyâ ve kardeşleri hapsedildi, malları alındı.'),
('وَدَهِشَ النَّاسُ، وَلَمْ يَعْرِفُوا سَبَبَ هَذِهِ النَّكْبَةِ.','İnsanlar şaşkına döndü ve bu felaketin sebebini bilemediler.'),
('فَقَالَ بَعْضُهُمْ: سَبَبُهَا الْعَبَّاسَةُ، وَقَالَ آخَرُونَ: سَبَبُهَا الْمَالُ وَالسُّلْطَةُ.','Bazıları sebebinin Abbâse olduğunu, bazıları ise mal ve iktidar olduğunu söyledi.'),
('وَأَكْثَرُ الْمُؤَرِّخِينَ يَرَوْنَ أَنَّ قِصَّةَ الْعَبَّاسَةِ ضَعِيفَةٌ، وَأَنَّ السَّبَبَ سِيَاسِيٌّ.','Tarihçilerin çoğu Abbâse hikâyesinin zayıf, sebebin ise siyasi olduğunu düşünür.')]),
('الْعِبْرَةُ','İbret',[
('وَمَاتَ يَحْيَى الْبَرْمَكِيُّ فِي السِّجْنِ شَيْخًا كَبِيرًا.','Yahyâ el-Bermekî zindanda çok yaşlı olarak öldü.'),
('وَقِيلَ إِنَّ ابْنَهُ سَأَلَهُ: «يَا أَبَتِ، بَعْدَ الْعِزِّ وَالْمُلْكِ صِرْنَا إِلَى هَذَا؟»','Denir ki oğlu ona sordu: “Babacığım, izzet ve hükümranlıktan sonra bu hâle mi düştük?”'),
('فَقَالَ: «يَا بُنَيَّ، دَعْوَةُ مَظْلُومٍ سَرَتْ بِلَيْلٍ، غَفَلْنَا عَنْهَا، وَلَمْ يَغْفُلِ اللَّهُ عَنْهَا.»','Dedi ki: “Oğlum, bir mazlumun gece yürüyen duası; biz ondan gafil kaldık ama Allah gafil kalmadı.”'),
('وَنَدِمَ الرَّشِيدُ بَعْدَ ذَلِكَ، وَكَانَ إِذَا ذُكِرَ الْبَرَامِكَةُ بَكَى.','Reşîd bundan sonra pişman oldu; Bermekîler anıldığında ağlardı.'),
('قَالَ زَيْدَانُ فِي رِوَايَتِهِ إِنَّ السُّلْطَةَ الْمُطْلَقَةَ تُفْسِدُ الْقُلُوبَ، حَتَّى قُلُوبَ الْأَصْدِقَاءِ.','Zeydân romanında mutlak iktidarın kalpleri, dostların kalplerini bile bozduğunu anlatır.')]),
]
